<?php
if(!defined('ABSPATH')){exit;}
final class AICS_SEO_Link_Insertion_Service{
	public function insert(string $content,array $records,string $kind):array{$report=array();foreach($records as $record){$url=esc_url_raw((string)($record['verified_url']??''),array('http','https'));$anchor=substr(sanitize_text_field((string)($record['anchor_text']??'')),0,100);$entry=$record;if(''===$url||''===$anchor){$entry['status']='failed';$entry['reason']=$kind.'_link_candidate_invalid';$report[]=$entry;continue;}if($this->has_url($content,$url)){$entry['status']='inserted';$entry['reason']='already_present';$report[]=$entry;continue;}$inserted=false;$pattern='/<p\b([^>]*)>(.*?)<\/p>/is';$content=preg_replace_callback($pattern,function($m)use($url,$anchor,&$inserted){if($inserted||preg_match('/<(?:a|code|pre|script|style|button|figcaption)\b/i',$m[2])||wp_strip_all_tags($m[2])!==$m[2]){return $m[0];}$quoted=preg_quote($anchor,'/');$changed=preg_replace('/(?<![\pL\pN])'.$quoted.'(?![\pL\pN])/iu','<a href="'.esc_url($url).'">'.esc_html($anchor).'</a>',$m[2],1,$count);if($count){$inserted=true;return '<p'.$m[1].'>'.$changed.'</p>';}return $m[0];},$content)??$content;$entry['status']=$inserted?'inserted':'recommended';$entry['reason']=$inserted?'inserted_in_paragraph':'no_safe_insertion_location';$report[]=$entry;}return array('content'=>$content,'records'=>$report,'changed'=>count(array_filter($report,static fn($r)=>'inserted'===($r['status']??'')&&'already_present'!==($r['reason']??'')))>0);}
	private function has_url(string $content,string $url):bool{if(!preg_match_all('/<a\s[^>]*href=["\']([^"\']+)["\']/i',$content,$m)){return false;}$needle=untrailingslashit($url);foreach($m[1] as $existing){if(untrailingslashit(esc_url_raw(html_entity_decode($existing)))===$needle){return true;}}return false;}
}
